\begin{figure}
    \centering
\begin{tikzpicture}[node distance=2cm,
    every node/.style={fill=white, font=\sffamily}, align=center]

  \node (start)             [activityStarts]              {New incoming transaction};
  \node (isConflicting)     [decision, below of=start, yshift=-0.5cm]          {Is directly conflicting?};
 \node (updateConflictDAG) [process, below of = isConflicting, yshift=-0.5cm] {Update Conflict DAG; Algorithm \ref{alg: updating Conflict DAG}};
 \node (updateConflictGraph) [processOpt, below of = updateConflictDAG ] {Update Conflict Graph, Algorithm \ref{alg:updateConflictGraph} (optional)}; 
 \node (branchID) [processOpt, below  of = updateConflictGraph] { Update branches of transactions (optional)};
 \node (updateW) [processExt, below of = branchID] { Update weights, e.g. Examples \ref{ex:min} \ref{ex:minTS}, \ref{ex:extConsensus} (external)};
 \node (reality) [processOpt, below of = updateW] {Select Reality, Algorithm \ref{alg:selectionBranch} or \ref{alg:selectionConflictGraph} (optional)};
  \node (pruning) [process, below of = reality] {Prune of Conflict DAG and Conflict Graph, Algorithm \ref{alg: update UTXO DAG after confirmation}};

   \node (issue) [startstop, below of = pruning] { Issue  new transaction (optional)};


  \draw[->]             (start.south) -- (isConflicting);
  \draw[->]            (isConflicting.south) -- node {yes} (updateConflictDAG) ;
  \draw[->]           (updateConflictDAG) --  (updateConflictGraph) ;
  \draw[->]             (updateConflictGraph.south) -| (branchID.north) ;
  \draw[->]     (isConflicting.east)  --  node {no} ++(3,0) -- ++(0,-6) |-
                                    (branchID.east);
    \draw[->]             (branchID) -- (updateW);     
    \draw[->]             (updateW) --  (reality);
\draw[->]            (reality) -- (pruning)  ;
     \draw[->]            (pruning) --  (issue);               
\end{tikzpicture}
\caption{Flow of the different operations on the reality-based ledger. }
\label{fig:ProcessFlow}
\end{figure}

